sys_script_include.script:
var OrderAjaxUtils = Class.create();
  OrderAjaxUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

      getOpenOrderCount: function() {
          var item = this.getParameter('sysparm_item');
          if (!item) return '0';
          var ga = new GlideAggregate('x_..._order');
          ga.addQuery('item', item);
          ga.addQuery('state', 'NOT IN', 'fulfilled,cancelled');
          ga.addAggregate('COUNT');
          ga.query();
          return ga.next() ? ga.getAggregate('COUNT') : '0';
      },

      type: 'OrderAjaxUtils'
  });
